//! Recording a measurement for the accuracy document
//! (`docs/05-testing/ACCURACY.md`, generated by `cargo xtask accuracy`):
//! a test that measures the SDK against a recorded reference calls
//! [`record`] with its worst difference, and when `TEISTRO_ACCURACY_DIR`
//! is set the measurement is appended as one JSON line to
//! `measurements.jsonl` in that directory. Without the variable the call
//! does nothing, so an ordinary `cargo test` leaves no file behind.

#![allow(
    dead_code,
    reason = "each test binary uses the part of this module it needs"
)]

use std::io::Write as _;

/// The environment variable naming the directory the measurements go to.
pub(crate) const DIR_ENV: &str = "TEISTRO_ACCURACY_DIR";

/// The file the measurements are appended to, inside that directory.
pub(crate) const FILE: &str = "measurements.jsonl";

/// Records the worst difference a comparison found: `row` is the accuracy
/// document's row (`houses`, `ayanamsha`, ...), `quantity` names what was
/// compared, `value` is the worst difference in `unit`, `bound` the bound
/// the test holds it to, `count` how many values were compared.
pub(crate) fn record(row: &str, quantity: &str, value: f64, unit: &str, bound: f64, count: usize) {
    let Some(dir) = std::env::var_os(DIR_ENV) else {
        return;
    };
    let line = serde_json::json!({
        "row": row,
        "quantity": quantity,
        "value": value,
        "unit": unit,
        "bound": bound,
        "count": count,
    });
    let path = std::path::Path::new(&dir).join(FILE);
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
        .unwrap_or_else(|error| panic!("cannot open {}: {error}", path.display()));
    // One line per call, written whole: appends of a short line do not
    // interleave.
    writeln!(file, "{line}")
        .unwrap_or_else(|error| panic!("cannot write {}: {error}", path.display()));
}
